ActionExecuteScript.Script:
using Simulant.Game.Data;
using Map = Lumina.Excel.Sheets.Map;
using Simulant.Utils;
using System;
using System.Collections.Generic;
using static Triggernometry.Core.Scripting.ScriptHelper;

Triggernometry.Core.RealPlugin.Instance.RegisterNamedCallback(
    "Kairos_GetMapData", new Action<object, string>(GetMapData), registrant: "Kairos");

void GetMapData(object _, string data)
{
    SetDictVariable(false, "Kairos_Map", null);

    var mapId = data.ParseData<ushort>();
    var sheet = GameDataService.Instance.GetSheet<Map>();
    if (!sheet.TryGetRow(mapId, out var map))
        throw new Exception($"未找到地图数据：{mapId}");

    var mapData = new Dictionary<string, string>
    {
        ["SizeFactor"] = map.SizeFactor.ToStringInvariant(),
        ["OffsetX"] = map.OffsetX.ToStringInvariant(),
        ["OffsetY"] = map.OffsetY.ToStringInvariant(),
    };

    SetDictVariable(false, "Kairos_Map", new Triggernometry.Core.Variables.VariableDictionary(mapData));
    CustomLog($"MapID = {mapId}, SizeFactor = {map.SizeFactor}, OffsetX = {map.OffsetX}, OffsetY = {map.OffsetY}");
}
